--
-- Name: v_dac7_fees_quarter; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_dac7_fees_quarter AS
 SELECT ((to_char((issued_on)::timestamp with time zone, 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM issued_on))::integer) AS quarter,
    billing_entity_id,
    max((buyer ->> 'legalName'::text)) AS legal_name,
    (sum(gross_total))::bigint AS fee_gross
   FROM public.invoices
  WHERE (status = ANY (ARRAY['issued'::text, 'sent'::text]))
  GROUP BY ((to_char((issued_on)::timestamp with time zone, 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM issued_on))::integer), billing_entity_id;


--
-- Name: v_icp_listing_quarter; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_icp_listing_quarter AS
 SELECT ((to_char((issued_on)::timestamp with time zone, 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM issued_on))::integer) AS quarter,
    (buyer ->> 'vatId'::text) AS vat_id,
    upper(SUBSTRING((buyer ->> 'vatId'::text) FROM 1 FOR 2)) AS country_code,
    (sum(net_total))::bigint AS rc_net
   FROM public.invoices
  WHERE ((status = ANY (ARRAY['issued'::text, 'sent'::text])) AND (vat_treatment = 'EU_REVERSE_CHARGE'::text))
  GROUP BY ((to_char((issued_on)::timestamp with time zone, 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM issued_on))::integer), (buyer ->> 'vatId'::text), (upper(SUBSTRING((buyer ->> 'vatId'::text) FROM 1 FOR 2)));


--
-- Name: v_returned_payments_quarter; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_returned_payments_quarter AS
 SELECT ((to_char((occurred_at AT TIME ZONE 'Europe/Amsterdam'::text), 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM (occurred_at AT TIME ZONE 'Europe/Amsterdam'::text)))::integer) AS quarter,
    billing_entity_id,
    stripe_account_id,
    stripe_payment_ref,
    stripe_application_fee_id,
    gross_amount AS fee_gross,
    (COALESCE(( SELECT (- sum(r.gross_amount))
           FROM public.commission_entries r
          WHERE (r.refunds_entry_id = f.id)), (0)::numeric))::bigint AS refunded_gross,
    ((occurred_at AT TIME ZONE 'Europe/Amsterdam'::text))::date AS returned_on
   FROM public.commission_entries f
  WHERE ((disposition = 'returned'::text) AND (kind = 'fee'::text));


--
-- Name: v_vat_return_quarter; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_vat_return_quarter AS
 SELECT ((to_char((issued_on)::timestamp with time zone, 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM issued_on))::integer) AS quarter,
    (COALESCE(sum(net_total) FILTER (WHERE (vat_treatment = 'NL_DOMESTIC'::text)), (0)::numeric))::bigint AS nl_net,
    (COALESCE(sum(vat_total) FILTER (WHERE (vat_treatment = 'NL_DOMESTIC'::text)), (0)::numeric))::bigint AS nl_vat,
    (COALESCE(sum(net_total) FILTER (WHERE (vat_treatment = 'EU_REVERSE_CHARGE'::text)), (0)::numeric))::bigint AS rc_net
   FROM public.invoices
  WHERE (status = ANY (ARRAY['issued'::text, 'sent'::text]))
  GROUP BY ((to_char((issued_on)::timestamp with time zone, 'YYYY'::text) || 'Q'::text) || (EXTRACT(quarter FROM issued_on))::integer);


--
-- Name: verification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.verification (
    id text NOT NULL,
    identifier text NOT NULL,
    value text NOT NULL,
    "expiresAt" timestamp with time zone NOT NULL,
    "createdAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


